/* HEXA BATTLEGROUNDS setup — PART 29 OF 57. Run parts in order. Safe to re-run. */ insert into mission_templates(id, family, kind, title, category, difficulty, tags, objective, clues, parts, relay, attempts, time_limit, hint, explanation, points, coins, status) values ('mission-sudoku-4', 'sudoku', 'mission', 'Mini Sudoku Vault', 'logic', 2, array['any','learning','office','glass','observation','phase2']::text[], 'A 4×4 sudoku: every row, column and 2×2 box holds 1, 2, 3, 4 once. Scout holds the top half, Decoder the bottom half. Intel knows which cells make the code.', '{"scout":{"title":"Top half (rows 1–2)","body":"· · 3 ·\n4 · · ·\n— — — —\n? ? ? ?\n? ? ? ?","mono":true,"grid":{"rows":[[0,0,3,0],[4,0,0,0],null,null]}},"decoder":{"title":"Bottom half (rows 3–4)","body":"? ? ? ?\n? ? ? ?\n— — — —\n1 2 · ·\n3 4 2 1","mono":true,"grid":{"rows":[null,null,[1,2,0,0],[3,4,2,1]]}},"intel":{"title":"Code cells","body":"A = row 1, column 4\nB = row 1, column 2\nC = row 2, column 4\nD = row 3, column 4\n\nCode = A B C D","mono":true}}'::jsonb, '[{"label":"4-digit code","accept":["4123"]}]'::jsonb, false, 3, 240, 'Fill the cells you are sure of first: a row or 2×2 box with three numbers has only one choice left.', 'Solved grid: 2134 / 4312 / 1243 / 3421 → 4123', null, 25, 'published'), ('mission-sudoku-5', 'sudoku', 'mission', 'Mini Sudoku Vault', 'logic', 2, array['any','learning','office','glass','observation','phase2']::text[], 'A 4×4 sudoku: every row, column and 2×2 box holds 1, 2, 3, 4 once. Scout holds the top half, Decoder the bottom half. Intel knows which cells make the code.', '{"scout":{"title":"Top half (rows 1–2)","body":"· 3 1 2\n· 2 · ·\n— — — —\n? ? ? ?\n? ? ? ?","mono":true,"grid":{"rows":[[0,3,1,2],[0,2,0,0],null,null]}},"decoder":{"title":"Bottom half (rows 3–4)","body":"? ? ? ?\n? ? ? ?\n— — — —\n2 1 · 4\n· · 2 ·","mono":true,"grid":{"rows":[null,null,[2,1,0,4],[0,0,2,0]]}},"intel":{"title":"Code cells","body":"A = row 3, column 3\nB = row 2, column 4\nC = row 1, column 1\nD = row 4, column 4\n\nCode = A B C D","mono":true}}'::jsonb, '[{"label":"4-digit code","accept":["3341"]}]'::jsonb, false, 3, 240, 'Fill the cells you are sure of first: a row or 2×2 box with three numbers has only one choice left.', 'Solved grid: 4312 / 1243 / 2134 / 3421 → 3341', null, 25, 'published'), ('battle-sudoku-10', 'sudoku', 'battle', 'Mini Sudoku Vault', 'logic', 2, array['duel_sniper']::text[], 'A 4×4 sudoku: every row, column and 2×2 box holds 1, 2, 3, 4 once. Scout holds the top half, Decoder the bottom half. Intel knows which cells make the code.', '{"scout":{"title":"Top half (rows 1–2)","body":"2 · 3 4\n3 · · ·\n— — — —\n? ? ? ?\n? ? ? ?","mono":true,"grid":{"rows":[[2,0,3,4],[3,0,0,0],null,null]}},"decoder":{"title":"Bottom half (rows 3–4)","body":"? ? ? ?\n? ? ? ?\n— — — —\n1 · · 3\n· · 1 2","mono":true,"grid":{"rows":[null,null,[1,0,0,3],[0,0,1,2]]}},"intel":{"title":"Code cells","body":"A = row 1, column 2\nB = row 4, column 2\nC = row 2, column 4\nD = row 3, column 3\n\nCode = A B C D","mono":true}}'::jsonb, '[{"label":"4-digit code","accept":["1314"]}]'::jsonb, false, 3, 120, 'Fill the cells you are sure of first: a row or 2×2 box with three numbers has only one choice left.', 'Solved grid: 2134 / 3421 / 1243 / 4312 → 1314', null, 25, 'published'), ('battle-sudoku-11', 'sudoku', 'battle', 'Mini Sudoku Vault', 'logic', 2, array['duel_sniper']::text[], 'A 4×4 sudoku: every row, column and 2×2 box holds 1, 2, 3, 4 once. Scout holds the top half, Decoder the bottom half. Intel knows which cells make the code.', '{"scout":{"title":"Top half (rows 1–2)","body":"1 4 2 ·\n· · 4 1\n— — — —\n? ? ? ?\n? ? ? ?","mono":true,"grid":{"rows":[[1,4,2,0],[0,0,4,1],null,null]}},"decoder":{"title":"Bottom half (rows 3–4)","body":"? ? ? ?\n? ? ? ?\n— — — —\n· 3 · 4\n· · 3 ·","mono":true,"grid":{"rows":[null,null,[0,3,0,4],[0,0,3,0]]}},"intel":{"title":"Code cells","body":"A = row 3, column 3\nB = row 2, column 1\nC = row 4, column 2\nD = ro